import { useEffect, useMemo, useState } from 'react'
import { BriefcaseBusiness, CalendarDays, Clock3, FileText, Plus, RefreshCw, Search, ShieldCheck, UserRound, UserRoundX, WalletCards, X } from 'lucide-react'
import { api } from '../lib/api'
import { EmptyState, ErrorState, LoadingState, PageHeader, StatusBadge, useConfirmation } from '../components/ui'

type Branch = { id: string; name: string; store_code?: string }
type UserOption = { id: number; name: string; email: string; status?: string }
type Employee = { id: string; name?: string | null; employee_number: string; job_title?: string | null; department?: string | null; employment_type: string; hire_date?: string | null; employment_status: string; phone?: string | null; address?: string | null; emergency_contact_name?: string | null; emergency_contact_phone?: string | null; notes?: string | null; photo_available?: boolean; photo_url?: string | null; user?: UserOption | null; branches?: Array<{ membership_id?: number | null; id: string; name: string; role: string; status: string }> }
type Page<T> = { data: T[]; current_page: number; last_page: number; total: number; per_page: number }
type Attendance = { id: string; employee_id?: string; employee_name?: string; store?: string; work_date?: string; clock_in?: string; clock_out?: string; status: string; overtime_minutes: number; notes?: string }
type Leave = { id: string; employee_id?: string; employee_name?: string; leave_type: string; starts_on: string; ends_on: string; reason?: string; status: string }
type Payroll = { id: string; employee_id?: string; employee_name?: string; period_start: string; period_end: string; base_salary: string; allowances: string; deductions: string; net_salary: string; currency_code: string; status: string }
type Commission = { id: string; employee_id?: string; employee_name?: string; sale_id?: number | null; commission_rate: string; base_amount: string; commission_amount: string; status: string; source_reference?: string | null; adjustment_reason?: string | null }
type Tab = 'directory' | 'attendance' | 'leave' | 'payroll' | 'commissions'

const inputClass = 'mt-1 w-full rounded-[10px] border border-slate-300 bg-white px-3 py-2.5 text-sm text-slate-900 outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100 dark:focus:border-blue-400 dark:focus:ring-blue-950'
const tabs: Array<{ id: Tab; label: string; icon: typeof BriefcaseBusiness }> = [
  { id: 'directory', label: 'Directory', icon: UserRound },
  { id: 'attendance', label: 'Attendance', icon: Clock3 },
  { id: 'leave', label: 'Leave', icon: CalendarDays },
  { id: 'payroll', label: 'Payroll', icon: WalletCards },
  { id: 'commissions', label: 'Commissions', icon: BriefcaseBusiness },
]

export function EmployeeManagementPage() {
  const { requestConfirmation } = useConfirmation()
  const [tab, setTab] = useState<Tab>('directory')
  const [employees, setEmployees] = useState<Page<Employee> | null>(null)
  const [branches, setBranches] = useState<Branch[]>([])
  const [users, setUsers] = useState<UserOption[]>([])
  const [search, setSearch] = useState('')
  const [status, setStatus] = useState('')
  const [branchId, setBranchId] = useState('')
  const [page, setPage] = useState(1)
  const [perPage, setPerPage] = useState(20)
  const [selected, setSelected] = useState<Employee | null>(null)
  const [showForm, setShowForm] = useState(false)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [attendance, setAttendance] = useState<Page<Attendance> | null>(null)
  const [leave, setLeave] = useState<Page<Leave> | null>(null)
  const [payroll, setPayroll] = useState<Page<Payroll> | null>(null)
  const [commissions, setCommissions] = useState<Page<Commission> | null>(null)

  const loadEmployees = async () => {
    setLoading(true); setError('')
    try {
      const [employeeResponse, branchResponse, memberResponse] = await Promise.all([
        api.get<{ data: Page<Employee> }>('/api/v1/business/employees', { params: { search: search || undefined, status: status || undefined, branch_id: branchId || undefined, page, per_page: perPage } }),
        api.get<{ data: Branch[] }>('/api/v1/business/stores'),
        api.get<{ data: Array<{ user: UserOption }> }>('/api/v1/business/members'),
      ])
      setEmployees(employeeResponse.data.data); setBranches(branchResponse.data.data || []); setUsers((memberResponse.data.data || []).map((item) => item.user))
    } catch (err) { setError(message(err, 'Unable to load employee records.')) } finally { setLoading(false) }
  }

  const loadTab = async (nextTab: Tab) => {
    if (nextTab === 'directory') return
    setLoading(true); setError('')
    try {
      const endpoints: Record<Exclude<Tab, 'directory'>, string> = { attendance: '/api/v1/business/employees/attendance', leave: '/api/v1/business/employees/leave', payroll: '/api/v1/business/employees/payroll', commissions: '/api/v1/business/employees/commissions' }
      const response = await api.get<{ data: Page<Attendance> | Page<Leave> | Page<Payroll> | Page<Commission> }>(endpoints[nextTab], { params: { page: 1, per_page: perPage } })
      if (nextTab === 'attendance') setAttendance(response.data.data as Page<Attendance>)
      if (nextTab === 'leave') setLeave(response.data.data as Page<Leave>)
      if (nextTab === 'payroll') setPayroll(response.data.data as Page<Payroll>)
      if (nextTab === 'commissions') setCommissions(response.data.data as Page<Commission>)
    } catch (err) { setError(message(err, `Unable to load ${nextTab} records.`)) } finally { setLoading(false) }
  }

  useEffect(() => { void loadEmployees() }, [page, perPage, status, branchId])
  useEffect(() => { if (tab !== 'directory') void loadTab(tab) }, [tab, perPage])

  const activeCount = useMemo(() => employees?.data.filter((employee) => employee.employment_status === 'active').length ?? 0, [employees])
  const openCreate = () => { setSelected(null); setShowForm(true); setNotice(''); setError('') }
  const openEdit = (employee: Employee) => { setSelected(employee); setShowForm(true); setNotice(''); setError('') }
  const onSaved = async (text: string) => { setShowForm(false); setNotice(text); await loadEmployees() }

  return <>
    <PageHeader title="Employee Management" description="Manage existing business users, branch access, attendance, leave, payroll approvals, and salesperson commissions." action={<div className="flex flex-wrap gap-2"><button type="button" onClick={() => { void loadEmployees() }} className="inline-flex items-center gap-2 rounded-[10px] border border-slate-300 bg-white px-3 py-2.5 text-sm font-semibold text-slate-700 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200"><RefreshCw size={16} />Refresh</button><button type="button" onClick={openCreate} className="inline-flex items-center gap-2 rounded-[10px] bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-blue-700"><Plus size={17} />Add employee</button></div>} />
    {error && <div className="mb-4"><ErrorState message={error} /></div>}
    {notice && <div role="status" className="mb-4 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm font-semibold text-emerald-800 dark:border-emerald-900/60 dark:bg-emerald-950/40 dark:text-emerald-200">{notice}</div>}
    <div className="mb-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Summary label="Employees" value={employees?.total ?? '—'} icon={UserRound} tone="blue" /><Summary label="Active on page" value={employees ? activeCount : '—'} icon={ShieldCheck} tone="green" /><Summary label="Branches" value={branches.length || '—'} icon={BriefcaseBusiness} tone="purple" /><Summary label="Access model" value="Tenant scoped" icon={FileText} tone="orange" /></div>
    <div className="mb-5 flex gap-1 overflow-x-auto rounded-xl border border-slate-200 bg-white p-1 dark:border-slate-800 dark:bg-slate-950">{tabs.map(({ id, label, icon: Icon }) => <button key={id} type="button" onClick={() => { setTab(id); setError('') }} className={`inline-flex shrink-0 items-center gap-2 rounded-lg px-3 py-2 text-sm font-semibold transition ${tab === id ? 'bg-blue-600 text-white' : 'text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800'}`}><Icon size={16} />{label}</button>)}</div>
    {tab === 'directory' && <Directory employees={employees} branches={branches} search={search} status={status} branchId={branchId} page={page} perPage={perPage} loading={loading} onSearch={(value) => { setSearch(value); setPage(1) }} onStatus={(value) => { setStatus(value); setPage(1) }} onBranch={(value) => { setBranchId(value); setPage(1) }} onPage={setPage} onPerPage={(value) => { setPerPage(value); setPage(1) }} onEdit={openEdit} onView={(employee) => { void viewEmployee(employee) }} onDeactivate={(employee) => { void deactivate(employee) }} onClockIn={(employee) => { void clockIn(employee) }} />}
    {tab === 'attendance' && <AttendancePanel records={attendance} loading={loading} onReload={() => { void loadTab('attendance') }} onClockOut={async (record) => { try { await api.post(`/api/v1/business/employees/attendance/${record.id}/clock-out`); setNotice('Attendance clocked out.'); await loadTab('attendance') } catch (err) { setError(message(err, 'Unable to clock out.')) } }} />}
    {tab === 'leave' && <LeavePanel records={leave} loading={loading} employees={employees?.data || []} onReload={() => { void loadTab('leave') }} onReview={async (record, statusValue) => { try { await api.post(`/api/v1/business/employees/leave/${record.id}/review`, { status: statusValue }); setNotice(`Leave request ${statusValue}.`); await loadTab('leave') } catch (err) { setError(message(err, 'Unable to review leave request.')) } }} onRequest={async (employeeId, form) => { try { await api.post(`/api/v1/business/employees/${employeeId}/leave`, form); setNotice('Leave request saved.'); await loadTab('leave') } catch (err) { setError(message(err, 'Unable to save leave request.')) } }} />}
    {tab === 'payroll' && <PayrollPanel records={payroll} loading={loading} employees={employees?.data || []} onReload={() => { void loadTab('payroll') }} onCreate={async (employeeId, form) => { try { await api.post(`/api/v1/business/employees/${employeeId}/payroll`, form); setNotice('Payroll record submitted for approval.'); await loadTab('payroll') } catch (err) { setError(message(err, 'Unable to save payroll record.')) } }} onApprove={async (id) => { try { await api.post(`/api/v1/business/employees/payroll/${id}/approve`); setNotice('Payroll approved.'); await loadTab('payroll') } catch (err) { setError(message(err, 'Unable to approve payroll.')) } }} />}
    {tab === 'commissions' && <CommissionPanel records={commissions} loading={loading} employees={employees?.data || []} onReload={() => { void loadTab('commissions') }} onCreate={async (employeeId, form) => { try { await api.post(`/api/v1/business/employees/${employeeId}/commissions`, form); setNotice('Commission record saved.'); await loadTab('commissions') } catch (err) { setError(message(err, 'Unable to save commission.')) } }} onReverse={async (id, reason) => { try { await api.post(`/api/v1/business/employees/commissions/${id}/reverse`, { reason }); setNotice('Commission reversal recorded.'); await loadTab('commissions') } catch (err) { setError(message(err, 'Unable to reverse commission.')) } }} />}
    {showForm && <EmployeeRegistrationForm employee={selected} users={users} branches={branches} saving={saving} onClose={() => setShowForm(false)} onSaving={setSaving} onSaved={onSaved} />}
    {selected && !showForm && <EmployeeDetail employee={selected} branches={branches} onClose={() => setSelected(null)} onRefresh={async () => { await viewEmployee(selected) }} />}
  </>

  async function viewEmployee(employee: Employee) { try { const response = await api.get<{ data: Employee & { documents?: unknown[]; attendance?: Attendance[] } }>(`/api/v1/business/employees/${employee.id}`); setSelected(response.data.data) } catch (err) { setError(message(err, 'Unable to load employee profile.')) } }
  function deactivate(employee: Employee) { requestConfirmation({ title: 'Deactivate employee', description: `Deactivate ${employee.user?.name || 'this employee'}? Branch and register access will be revoked while historical sales remain preserved.`, confirmLabel: 'Deactivate', cancelLabel: 'Cancel', tone: 'danger', successMessage: 'Employee deactivated and access revoked.' }, async () => { try { await api.post(`/api/v1/business/employees/${employee.id}/deactivate`); await loadEmployees() } catch (err) { return message(err, 'Unable to deactivate employee.') } }) }
  async function clockIn(employee: Employee) { try { await api.post(`/api/v1/business/employees/${employee.id}/attendance/clock-in`, { store_id: employee.branches?.[0]?.id }); setNotice('Employee clocked in.'); setTab('attendance'); await loadTab('attendance') } catch (err) { setError(message(err, 'Unable to clock in.')) } }
}

function Directory({ employees, branches, search, status, branchId, page, perPage, loading, onSearch, onStatus, onBranch, onPage, onPerPage, onEdit, onView, onDeactivate, onClockIn }: { employees: Page<Employee> | null; branches: Branch[]; search: string; status: string; branchId: string; page: number; perPage: number; loading: boolean; onSearch: (value: string) => void; onStatus: (value: string) => void; onBranch: (value: string) => void; onPage: (value: number) => void; onPerPage: (value: number) => void; onEdit: (employee: Employee) => void; onView: (employee: Employee) => void; onDeactivate: (employee: Employee) => void; onClockIn: (employee: Employee) => void }) {
  return <section className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-950 sm:p-5"><div className="mb-4 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div className="flex flex-1 flex-col gap-2 sm:flex-row"><label className="relative block min-w-0 flex-1 sm:max-w-[360px]"><Search className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input aria-label="Search employees" value={search} onChange={(event) => onSearch(event.target.value)} placeholder="Search name, email, employee ID" className={`${inputClass} mt-0 h-10 pl-10`} /></label><select aria-label="Filter employment status" value={status} onChange={(event) => onStatus(event.target.value)} className={`${inputClass} mt-0 h-10 sm:w-44`}><option value="">All statuses</option><option value="active">Active</option><option value="on_leave">On leave</option><option value="suspended">Suspended</option><option value="terminated">Terminated</option></select><select aria-label="Filter branch" value={branchId} onChange={(event) => onBranch(event.target.value)} className={`${inputClass} mt-0 sm:w-48`}><option value="">All branches</option>{branches.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></div><div className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400"><span>Rows</span><select value={perPage} onChange={(event) => onPerPage(Number(event.target.value))} className="rounded-lg border border-slate-300 bg-white px-2 py-2 dark:border-slate-700 dark:bg-slate-900"><option value={10}>10</option><option value={20}>20</option><option value={50}>50</option><option value={100}>100</option></select></div></div>{loading ? <LoadingState /> : !employees?.data.length ? <EmptyState label="No employee profiles found. Add a profile for an existing business user." /> : <div className="overflow-x-auto rounded-xl border border-slate-200 dark:border-slate-800"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase tracking-wide text-slate-500 dark:bg-slate-900 dark:text-slate-400"><tr><th className="px-4 py-3">Employee</th><th className="px-4 py-3">Role / department</th><th className="px-4 py-3">Branches</th><th className="px-4 py-3">Employment</th><th className="px-4 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{employees.data.map((employee) => <tr key={employee.id} className="hover:bg-slate-50/80 dark:hover:bg-slate-900/60"><td className="px-4 py-3"><button type="button" onClick={() => onView(employee)} className="text-left"><p className="font-semibold text-slate-900 hover:text-blue-700 dark:text-slate-100 dark:hover:text-blue-300">{employee.user?.name || 'Unnamed user'}</p><p className="text-xs text-slate-500 dark:text-slate-400">{employee.employee_number} · {employee.user?.email}</p></button></td><td className="px-4 py-3 text-slate-700 dark:text-slate-300">{employee.job_title || '—'}<span className="block text-xs text-slate-500">{employee.department || 'No department'}</span></td><td className="px-4 py-3 text-slate-700 dark:text-slate-300">{employee.branches?.length ? employee.branches.map((branch) => branch.name).join(', ') : 'Unassigned'}</td><td className="px-4 py-3"><StatusBadge status={employee.employment_status} /><span className="mt-1 block text-xs capitalize text-slate-500">{employee.employment_type.replaceAll('_', ' ')}</span></td><td className="px-4 py-3"><div className="flex justify-end gap-1.5"><button type="button" onClick={() => onClockIn(employee)} disabled={employee.employment_status !== 'active'} className="rounded-lg border border-emerald-200 px-2.5 py-2 text-xs font-semibold text-emerald-700 disabled:opacity-40 dark:border-emerald-900/60 dark:text-emerald-300">Clock in</button><button type="button" onClick={() => onEdit(employee)} className="rounded-lg border border-slate-300 px-2.5 py-2 text-xs font-semibold text-slate-700 dark:border-slate-700 dark:text-slate-200">Edit</button><button type="button" onClick={() => onDeactivate(employee)} disabled={employee.employment_status === 'terminated'} aria-label={`Deactivate ${employee.user?.name || employee.employee_number}`} className="rounded-lg border border-rose-200 p-2 text-rose-700 disabled:opacity-40 dark:border-rose-900/60 dark:text-rose-300"><UserRoundX size={15} /></button></div></td></tr>)}</tbody></table></div>}<Pagination page={page} lastPage={employees?.last_page || 1} total={employees?.total || 0} onPage={onPage} /></section>
}

function AttendancePanel({ records, loading, onReload, onClockOut }: { records: Page<Attendance> | null; loading: boolean; onReload: () => void; onClockOut: (record: Attendance) => Promise<void> }) { return <Panel title="Attendance records" icon={Clock3} action={<button type="button" onClick={onReload} className="rounded-lg border border-slate-300 p-2 text-slate-600 dark:border-slate-700 dark:text-slate-300"><RefreshCw size={16} /></button>}>{loading ? <LoadingState /> : !records?.data.length ? <EmptyState label="No attendance records yet." /> : <div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="text-xs uppercase text-slate-500"><tr><th className="px-3 py-3">Employee</th><th className="px-3 py-3">Date</th><th className="px-3 py-3">Clock in</th><th className="px-3 py-3">Clock out</th><th className="px-3 py-3">Status</th><th /></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{records.data.map((record) => <tr key={record.id}><td className="px-3 py-3 font-semibold text-slate-900 dark:text-slate-100">{record.employee_name || '—'}</td><td className="px-3 py-3 text-slate-600 dark:text-slate-300">{record.work_date || '—'}</td><td className="px-3 py-3 text-slate-600 dark:text-slate-300">{dateTime(record.clock_in)}</td><td className="px-3 py-3 text-slate-600 dark:text-slate-300">{dateTime(record.clock_out)}</td><td className="px-3 py-3"><StatusBadge status={record.status} /></td><td className="px-3 py-3 text-right">{record.clock_in && !record.clock_out && <button type="button" onClick={() => { void onClockOut(record) }} className="rounded-lg bg-blue-600 px-3 py-2 text-xs font-semibold text-white">Clock out</button>}</td></tr>)}</tbody></table></div>}</Panel> }

function LeavePanel({ records, loading, employees, onReload, onReview, onRequest }: { records: Page<Leave> | null; loading: boolean; employees: Employee[]; onReload: () => void; onReview: (record: Leave, status: 'approved' | 'rejected') => Promise<void>; onRequest: (employeeId: string, form: Record<string, string>) => Promise<void> }) { const [employeeId, setEmployeeId] = useState(''); const [form, setForm] = useState({ leave_type: 'annual', starts_on: '', ends_on: '', reason: '' }); return <Panel title="Leave management" icon={CalendarDays} action={<button type="button" onClick={onReload} className="rounded-lg border border-slate-300 p-2 text-slate-600 dark:border-slate-700 dark:text-slate-300"><RefreshCw size={16} /></button>}><div className="mb-5 grid gap-3 rounded-xl border border-slate-200 bg-slate-50 p-4 dark:border-slate-800 dark:bg-slate-900 md:grid-cols-5"><select value={employeeId} onChange={(event) => setEmployeeId(event.target.value)} className={`${inputClass} mt-0`}><option value="">Employee</option>{employees.map((employee) => <option key={employee.id} value={employee.id}>{employee.user?.name} · {employee.employee_number}</option>)}</select><select value={form.leave_type} onChange={(event) => setForm({ ...form, leave_type: event.target.value })} className={`${inputClass} mt-0`}><option value="annual">Annual</option><option value="sick">Sick</option><option value="unpaid">Unpaid</option><option value="other">Other</option></select><input type="date" value={form.starts_on} onChange={(event) => setForm({ ...form, starts_on: event.target.value })} className={`${inputClass} mt-0`} /><input type="date" value={form.ends_on} onChange={(event) => setForm({ ...form, ends_on: event.target.value })} className={`${inputClass} mt-0`} /><button type="button" disabled={!employeeId || !form.starts_on || !form.ends_on} onClick={() => { void onRequest(employeeId, form) }} className="rounded-[10px] bg-blue-600 px-3 py-2.5 text-sm font-semibold text-white disabled:opacity-50">Request leave</button></div>{loading ? <LoadingState /> : !records?.data.length ? <EmptyState label="No leave requests found." /> : <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left text-sm"><thead className="text-xs uppercase text-slate-500"><tr><th className="px-3 py-3">Employee</th><th className="px-3 py-3">Type</th><th className="px-3 py-3">Dates</th><th className="px-3 py-3">Status</th><th /></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{records.data.map((record) => <tr key={record.id}><td className="px-3 py-3 font-semibold text-slate-900 dark:text-slate-100">{record.employee_name}</td><td className="px-3 py-3 capitalize text-slate-600 dark:text-slate-300">{record.leave_type}</td><td className="px-3 py-3 text-slate-600 dark:text-slate-300">{record.starts_on} → {record.ends_on}</td><td className="px-3 py-3"><StatusBadge status={record.status} /></td><td className="px-3 py-3 text-right">{record.status === 'pending' && <span className="inline-flex gap-2"><button type="button" onClick={() => { void onReview(record, 'approved') }} className="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-semibold text-white">Approve</button><button type="button" onClick={() => { void onReview(record, 'rejected') }} className="rounded-lg border border-rose-200 px-3 py-2 text-xs font-semibold text-rose-700">Reject</button></span>}</td></tr>)}</tbody></table></div>}</Panel> }

function PayrollPanel({ records, loading, employees, onReload, onCreate, onApprove }: { records: Page<Payroll> | null; loading: boolean; employees: Employee[]; onReload: () => void; onCreate: (employeeId: string, form: Record<string, string>) => Promise<void>; onApprove: (id: string) => Promise<void> }) { const [employeeId, setEmployeeId] = useState(''); const [form, setForm] = useState({ period_start: '', period_end: '', base_salary: '', allowances: '0', deductions: '0', currency_code: 'MMK', notes: '' }); return <Panel title="Payroll approvals" icon={WalletCards} action={<button type="button" onClick={onReload} className="rounded-lg border border-slate-300 p-2 text-slate-600 dark:border-slate-700 dark:text-slate-300"><RefreshCw size={16} /></button>}><div className="mb-5 grid gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4 dark:border-amber-900/60 dark:bg-amber-950/20 md:grid-cols-4"><select value={employeeId} onChange={(event) => setEmployeeId(event.target.value)} className={`${inputClass} mt-0`}><option value="">Employee</option>{employees.map((employee) => <option key={employee.id} value={employee.id}>{employee.user?.name}</option>)}</select><input type="date" value={form.period_start} onChange={(event) => setForm({ ...form, period_start: event.target.value })} className={`${inputClass} mt-0`} /><input type="date" value={form.period_end} onChange={(event) => setForm({ ...form, period_end: event.target.value })} className={`${inputClass} mt-0`} /><div className="flex gap-2"><input type="number" min="0" placeholder="Base salary" value={form.base_salary} onChange={(event) => setForm({ ...form, base_salary: event.target.value })} className={`${inputClass} mt-0 min-w-0`} /><button type="button" disabled={!employeeId || !form.period_start || !form.period_end || !form.base_salary} onClick={() => { void onCreate(employeeId, form) }} className="rounded-[10px] bg-blue-600 px-3 py-2 text-sm font-semibold text-white disabled:opacity-50">Add</button></div><input placeholder="Allowances" type="number" min="0" value={form.allowances} onChange={(event) => setForm({ ...form, allowances: event.target.value })} className={`${inputClass} mt-0`} /><input placeholder="Deductions" type="number" min="0" value={form.deductions} onChange={(event) => setForm({ ...form, deductions: event.target.value })} className={`${inputClass} mt-0`} /></div>{loading ? <LoadingState /> : !records?.data.length ? <EmptyState label="No payroll records found." /> : <div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead className="text-xs uppercase text-slate-500"><tr><th className="px-3 py-3">Employee</th><th className="px-3 py-3">Period</th><th className="px-3 py-3">Net salary</th><th className="px-3 py-3">Status</th><th /></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{records.data.map((record) => <tr key={record.id}><td className="px-3 py-3 font-semibold text-slate-900 dark:text-slate-100">{record.employee_name}</td><td className="px-3 py-3 text-slate-600 dark:text-slate-300">{record.period_start} → {record.period_end}</td><td className="px-3 py-3 font-semibold text-slate-900 dark:text-slate-100">{money(record.net_salary)} {record.currency_code}</td><td className="px-3 py-3"><StatusBadge status={record.status} /></td><td className="px-3 py-3 text-right">{record.status === 'pending_approval' && <button type="button" onClick={() => { void onApprove(record.id) }} className="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-semibold text-white">Approve</button>}</td></tr>)}</tbody></table></div>}</Panel> }

function CommissionPanel({ records, loading, employees, onReload, onCreate, onReverse }: { records: Page<Commission> | null; loading: boolean; employees: Employee[]; onReload: () => void; onCreate: (employeeId: string, form: Record<string, string>) => Promise<void>; onReverse: (id: string, reason: string) => Promise<void> }) { const { requestConfirmation } = useConfirmation(); const [employeeId, setEmployeeId] = useState(''); const [form, setForm] = useState({ commission_rate: '', base_amount: '', sale_id: '', source_reference: '' }); const reverse = (id: string) => { requestConfirmation({ title: 'Reverse commission', description: 'Create an auditable negative reversal entry. The original commission will remain unchanged.', confirmLabel: 'Reverse commission', cancelLabel: 'Cancel', tone: 'danger', input: { label: 'Reversal reason', placeholder: 'Explain the refund or adjustment reason', required: true } }, async (reason) => { if (!reason.trim()) return 'A reversal reason is required.'; await onReverse(id, reason) }) }; return <Panel title="Sales commissions" icon={BriefcaseBusiness} action={<button type="button" onClick={onReload} className="rounded-lg border border-slate-300 p-2 text-slate-600 dark:border-slate-700 dark:text-slate-300"><RefreshCw size={16} /></button>}><div className="mb-5 grid gap-3 rounded-xl border border-violet-200 bg-violet-50 p-4 dark:border-violet-900/60 dark:bg-violet-950/20 md:grid-cols-5"><select value={employeeId} onChange={(event) => setEmployeeId(event.target.value)} className={`${inputClass} mt-0`}><option value="">Salesperson</option>{employees.map((employee) => <option key={employee.id} value={employee.id}>{employee.user?.name}</option>)}</select><input type="number" min="0" max="100" step="0.01" placeholder="Rate %" value={form.commission_rate} onChange={(event) => setForm({ ...form, commission_rate: event.target.value })} className={`${inputClass} mt-0`} /><input type="number" min="0" step="0.01" placeholder="Base amount" value={form.base_amount} onChange={(event) => setForm({ ...form, base_amount: event.target.value })} className={`${inputClass} mt-0`} /><input placeholder="Sale ID (optional)" value={form.sale_id} onChange={(event) => setForm({ ...form, sale_id: event.target.value })} className={`${inputClass} mt-0`} /><button type="button" disabled={!employeeId || !form.commission_rate || !form.base_amount} onClick={() => { void onCreate(employeeId, form) }} className="rounded-[10px] bg-blue-600 px-3 py-2.5 text-sm font-semibold text-white disabled:opacity-50">Add commission</button></div>{loading ? <LoadingState /> : !records?.data.length ? <EmptyState label="No commission records found." /> : <div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead className="text-xs uppercase text-slate-500"><tr><th className="px-3 py-3">Employee</th><th className="px-3 py-3">Sale</th><th className="px-3 py-3">Rate</th><th className="px-3 py-3">Commission</th><th className="px-3 py-3">Status</th><th /></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-800">{records.data.map((record) => <tr key={record.id}><td className="px-3 py-3 font-semibold text-slate-900 dark:text-slate-100">{record.employee_name}</td><td className="px-3 py-3 text-slate-600 dark:text-slate-300">{record.sale_id || 'Manual'}</td><td className="px-3 py-3 text-slate-600 dark:text-slate-300">{record.commission_rate}%</td><td className="px-3 py-3 font-semibold text-slate-900 dark:text-slate-100">{money(record.commission_amount)}</td><td className="px-3 py-3"><StatusBadge status={record.status} /></td><td className="px-3 py-3 text-right">{record.status === 'accrued' && <button type="button" onClick={() => reverse(record.id)} className="rounded-lg border border-rose-200 px-3 py-2 text-xs font-semibold text-rose-700">Reverse</button>}</td></tr>)}</tbody></table></div>}</Panel> }

function EmployeeForm({ employee, users, branches, saving, onClose, onSaving, onSaved }: { employee: Employee | null; users: UserOption[]; branches: Branch[]; saving: boolean; onClose: () => void; onSaving: (saving: boolean) => void; onSaved: (message: string) => Promise<void> }) { const [form, setForm] = useState({ user_id: employee?.user?.id ? String(employee.user.id) : '', employee_number: employee?.employee_number || '', job_title: employee?.job_title || '', department: employee?.department || '', employment_type: employee?.employment_type || 'full_time', hire_date: employee?.hire_date || '', employment_status: employee?.employment_status || 'active', phone: employee?.phone || '', address: employee?.address || '', emergency_contact_name: employee?.emergency_contact_name || '', emergency_contact_phone: employee?.emergency_contact_phone || '', notes: '', branch_id: employee?.branches?.[0]?.id || '', branch_role: employee?.branches?.[0]?.role || 'sales_staff' }); const [photo, setPhoto] = useState<File | null>(null); const [preview, setPreview] = useState(''); const [error, setError] = useState(''); const submit = async () => { if (!form.user_id || !form.employee_number) return; onSaving(true); setError(''); const data = new FormData(); Object.entries(form).forEach(([key, value]) => { if (value) data.append(key, value) }); if (photo) data.append('photo', photo); try { if (employee) await api.post(`/api/v1/business/employees/${employee.id}/update`, data, { headers: { 'Content-Type': 'multipart/form-data' } }); else await api.post('/api/v1/business/employees', data, { headers: { 'Content-Type': 'multipart/form-data' } }); await onSaved(employee ? 'Employee profile updated.' : 'Employee profile created.') } catch (err) { setError(message(err, 'Unable to save employee profile.')) } finally { onSaving(false) } }; return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4"><div className="max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl dark:border-slate-800 dark:bg-slate-950 sm:p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-wide text-blue-600">{employee ? 'Edit employee' : 'New employee profile'}</p><h2 className="mt-1 text-xl font-bold text-slate-950 dark:text-white">Use an existing business user</h2><p className="mt-1 text-sm text-slate-500 dark:text-slate-400">Employee records do not create duplicate login identities.</p></div><button type="button" onClick={onClose} aria-label="Close" className="rounded-lg p-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800"><X size={20} /></button></div>{error && <div className="mt-4"><ErrorState message={error} /></div>}<div className="mt-5 grid gap-4 md:grid-cols-2"><label className="text-sm font-semibold text-slate-700 dark:text-slate-300 md:col-span-2">Existing user<select disabled={Boolean(employee)} value={form.user_id} onChange={(event) => setForm({ ...form, user_id: event.target.value })} className={inputClass}><option value="">Select a business user</option>{users.map((user) => <option key={user.id} value={user.id}>{user.name} · {user.email}</option>)}</select></label><Field label="Employee ID" value={form.employee_number} onChange={(value) => setForm({ ...form, employee_number: value })} /><Field label="Job title" value={form.job_title} onChange={(value) => setForm({ ...form, job_title: value })} /><Field label="Department" value={form.department} onChange={(value) => setForm({ ...form, department: value })} /><label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Employment type<select value={form.employment_type} onChange={(event) => setForm({ ...form, employment_type: event.target.value })} className={inputClass}><option value="full_time">Full time</option><option value="part_time">Part time</option><option value="contract">Contract</option><option value="temporary">Temporary</option></select></label><Field label="Hire date" type="date" value={form.hire_date} onChange={(value) => setForm({ ...form, hire_date: value })} /><label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Employment status<select value={form.employment_status} onChange={(event) => setForm({ ...form, employment_status: event.target.value })} className={inputClass}><option value="active">Active</option><option value="on_leave">On leave</option><option value="suspended">Suspended</option><option value="terminated">Terminated</option></select></label><Field label="Phone" value={form.phone} onChange={(value) => setForm({ ...form, phone: value })} /><Field label="Emergency contact" value={form.emergency_contact_name} onChange={(value) => setForm({ ...form, emergency_contact_name: value })} /><Field label="Emergency phone" value={form.emergency_contact_phone} onChange={(value) => setForm({ ...form, emergency_contact_phone: value })} /><Field label="Address" value={form.address} onChange={(value) => setForm({ ...form, address: value })} /><label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Branch<select disabled={Boolean(employee)} value={form.branch_id} onChange={(event) => setForm({ ...form, branch_id: event.target.value })} className={inputClass}><option value="">No branch assignment</option>{branches.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></label><label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Branch role<select disabled={Boolean(employee)} value={form.branch_role} onChange={(event) => setForm({ ...form, branch_role: event.target.value })} className={inputClass}><option value="sales_staff">Sales staff</option><option value="salesperson">Salesperson</option><option value="cashier">Cashier</option><option value="store_manager">Store manager</option><option value="inventory_manager">Inventory manager</option></select></label><label className="text-sm font-semibold text-slate-700 dark:text-slate-300 md:col-span-2">Profile photo<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => { const file = event.target.files?.[0]; if (!file) return; if (file.size > 5 * 1024 * 1024) { setError('Choose an image up to 5 MB.'); return } setPhoto(file); setPreview(URL.createObjectURL(file)) }} className={`${inputClass} file:mr-3 file:rounded-md file:border-0 file:bg-blue-50 file:px-3 file:py-1.5 file:text-sm file:font-semibold file:text-blue-700`} />{preview && <img src={preview} alt="Selected profile preview" className="mt-3 size-20 rounded-xl object-cover" />}</label></div><div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-[10px] border border-slate-300 px-4 py-2.5 text-sm font-semibold text-slate-700 dark:border-slate-700 dark:text-slate-200">Cancel</button><button type="button" disabled={saving || !form.user_id || !form.employee_number} onClick={() => { void submit() }} className="rounded-[10px] bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{saving ? 'Saving…' : 'Save employee'}</button></div></div></div> }

function EmployeeDetail({ employee, branches, onClose, onRefresh }: { employee: Employee & { documents?: unknown[]; attendance?: Attendance[] }; branches: Branch[]; onClose: () => void; onRefresh: () => Promise<void> }) { return <div className="fixed inset-0 z-40 flex justify-end bg-slate-950/40"><aside className="h-full w-full max-w-xl overflow-y-auto border-l border-slate-200 bg-white p-5 shadow-2xl dark:border-slate-800 dark:bg-slate-950"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wide text-blue-600">Employee profile</p><h2 className="mt-1 text-xl font-bold text-slate-950 dark:text-white">{employee.user?.name}</h2><p className="text-sm text-slate-500">{employee.employee_number} · {employee.user?.email}</p></div><button type="button" onClick={onClose} aria-label="Close" className="rounded-lg p-2 hover:bg-slate-100 dark:hover:bg-slate-800"><X size={20} /></button></div><EmployeePhoto employee={employee} /><div className="mt-5 grid gap-3 sm:grid-cols-2"><Detail label="Job title" value={employee.job_title} /><Detail label="Department" value={employee.department} /><Detail label="Employment" value={employee.employment_type.replaceAll('_', ' ')} /><Detail label="Hire date" value={employee.hire_date} /><Detail label="Phone" value={employee.phone} /><Detail label="Emergency" value={employee.emergency_contact_name ? `${employee.emergency_contact_name} · ${employee.emergency_contact_phone || '—'}` : null} /></div><section className="mt-6 rounded-xl border border-slate-200 p-4 dark:border-slate-800"><h3 className="font-semibold text-slate-900 dark:text-white">Branch assignments</h3>{employee.branches?.length ? <div className="mt-3 space-y-2">{employee.branches.map((branch) => <div key={branch.id} className="flex justify-between text-sm"><span className="text-slate-700 dark:text-slate-300">{branch.name}</span><span className="capitalize text-slate-500">{branch.role.replaceAll('_', ' ')}</span></div>)}</div> : <p className="mt-2 text-sm text-slate-500">No active branch assignments.</p>}</section><BranchAssignmentControls employee={employee} branches={branches} onRefresh={onRefresh} /><section className="mt-4 rounded-xl border border-slate-200 p-4 dark:border-slate-800"><h3 className="font-semibold text-slate-900 dark:text-white">Recent attendance</h3>{employee.attendance?.length ? <div className="mt-3 space-y-2">{employee.attendance.slice(0, 8).map((record) => <div key={record.id} className="flex justify-between text-sm"><span>{record.work_date}</span><span className="text-slate-500">{dateTime(record.clock_in)} → {dateTime(record.clock_out)}</span></div>)}</div> : <p className="mt-2 text-sm text-slate-500">No attendance history.</p>}</section><button type="button" onClick={() => { void onRefresh() }} className="mt-5 inline-flex items-center gap-2 rounded-lg border border-slate-300 px-3 py-2 text-sm font-semibold text-slate-700 dark:border-slate-700 dark:text-slate-200"><RefreshCw size={15} />Refresh profile</button></aside></div> }

function BranchAssignmentControls({ employee, branches, onRefresh }: { employee: Employee; branches: Branch[]; onRefresh: () => Promise<void> }) { const { requestConfirmation } = useConfirmation(); const [branchId, setBranchId] = useState(''); const [role, setRole] = useState('sales_staff'); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const available = branches.filter((branch) => !employee.branches?.some((assigned) => assigned.id === branch.id)); const save = async () => { if (!branchId) return; setSaving(true); setError(''); try { await api.post(`/api/v1/business/stores/${branchId}/members`, { user_id: employee.user?.id, role }); await onRefresh(); setBranchId('') } catch (err) { setError(message(err, 'Unable to update branch access.')) } finally { setSaving(false) } }; const update = async (branch: NonNullable<Employee['branches']>[number], nextRole: string) => { if (!branch.membership_id) return; try { await api.patch(`/api/v1/business/stores/${branch.id}/members/${branch.membership_id}`, { role: nextRole }); await onRefresh() } catch (err) { setError(message(err, 'Unable to update branch role.')) } }; const revoke = (branch: NonNullable<Employee['branches']>[number]) => { if (!branch.membership_id) return; requestConfirmation({ title: 'Revoke branch access', description: `Revoke ${employee.user?.name || 'employee'} from ${branch.name}?`, confirmLabel: 'Revoke access', cancelLabel: 'Cancel', tone: 'danger' }, async () => { try { await api.delete(`/api/v1/business/stores/${branch.id}/members/${branch.membership_id}`); await onRefresh() } catch (err) { return message(err, 'Unable to revoke branch access.') } }) }; return <section className="mt-4 rounded-xl border border-slate-200 p-4 dark:border-slate-800"><h3 className="font-semibold text-slate-900 dark:text-white">Manage branch access</h3>{error && <p className="mt-2 text-xs text-rose-600">{error}</p>}<div className="mt-3 flex flex-wrap gap-2">{employee.branches?.map((branch) => <div key={branch.id} className="flex w-full items-center gap-2 rounded-lg bg-slate-50 p-2 dark:bg-slate-900"><span className="min-w-0 flex-1 truncate text-sm">{branch.name}</span><select value={branch.role} onChange={(event) => { void update(branch, event.target.value) }} className="rounded-lg border border-slate-300 bg-white px-2 py-1.5 text-xs dark:border-slate-700 dark:bg-slate-950"><option value="sales_staff">Sales staff</option><option value="salesperson">Salesperson</option><option value="cashier">Cashier</option><option value="store_manager">Store manager</option><option value="inventory_manager">Inventory manager</option></select><button type="button" onClick={() => revoke(branch)} className="rounded-lg border border-rose-200 px-2 py-1.5 text-xs font-semibold text-rose-700">Revoke</button></div>)}</div>{available.length > 0 && <div className="mt-3 flex flex-wrap gap-2"><select value={branchId} onChange={(event) => setBranchId(event.target.value)} className={`${inputClass} mt-0 min-w-0 flex-1`}><option value="">Add branch access</option>{available.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select><select value={role} onChange={(event) => setRole(event.target.value)} className={`${inputClass} mt-0 w-40`}><option value="sales_staff">Sales staff</option><option value="salesperson">Salesperson</option><option value="cashier">Cashier</option><option value="store_manager">Store manager</option><option value="inventory_manager">Inventory manager</option></select><button type="button" disabled={!branchId || saving} onClick={() => { void save() }} className="rounded-lg bg-blue-600 px-3 py-2 text-xs font-semibold text-white disabled:opacity-50">Assign</button></div>}</section> }

function EmployeePhoto({ employee }: { employee: Employee }) { const [src, setSrc] = useState(''); useEffect(() => { let active = true; if (!employee.photo_url) { setSrc(''); return () => { active = false } } void api.get<Blob>(`/api/v1/business/employees/${employee.id}/photo`, { responseType: 'blob' }).then((response) => { if (active) setSrc(URL.createObjectURL(response.data)) }).catch(() => undefined); return () => { active = false; if (src) URL.revokeObjectURL(src) } }, [employee.id, employee.photo_url]); return <div className="mt-5 flex items-center gap-3">{src ? <img src={src} alt="Employee profile" className="size-16 rounded-xl object-cover" /> : <div className="flex size-16 items-center justify-center rounded-xl bg-blue-50 text-blue-700 dark:bg-blue-950/40 dark:text-blue-300"><UserRound size={25} /></div>}<div><p className="text-sm font-semibold text-slate-900 dark:text-slate-100">Profile photo</p><p className="text-xs text-slate-500">{employee.photo_available ? 'Stored securely for authorized users.' : 'No profile photo uploaded.'}</p></div></div> }

function Panel({ title, icon: Icon, action, children }: { title: string; icon: typeof BriefcaseBusiness; action?: React.ReactNode; children: React.ReactNode }) { return <section className="rounded-2xl border border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-950 sm:p-5"><div className="mb-4 flex items-center justify-between gap-3"><h2 className="inline-flex items-center gap-2 font-bold text-slate-950 dark:text-white"><span className="rounded-lg bg-blue-50 p-2 text-blue-700 dark:bg-blue-950/40 dark:text-blue-300"><Icon size={17} /></span>{title}</h2>{action}</div>{children}</section> }
function Summary({ label, value, icon: Icon, tone }: { label: string; value: string | number; icon: typeof BriefcaseBusiness; tone: 'blue' | 'green' | 'purple' | 'orange' }) { const tones = { blue: 'border-blue-500 bg-blue-50 text-blue-700', green: 'border-emerald-500 bg-emerald-50 text-emerald-700', purple: 'border-violet-500 bg-violet-50 text-violet-700', orange: 'border-orange-500 bg-orange-50 text-orange-700' }; return <div className={`rounded-xl border border-l-4 border-slate-200 bg-white p-4 dark:border-slate-800 dark:bg-slate-950 ${tones[tone]}`}><div className="flex items-center justify-between"><span className="text-sm font-medium text-slate-600 dark:text-slate-400">{label}</span><span className="rounded-lg bg-white/80 p-2 dark:bg-slate-900"><Icon size={18} /></span></div><p className="mt-2 text-xl font-bold text-slate-950 dark:text-white">{value}</p></div> }
function Field({ label, value, onChange, type = 'text' }: { label: string; value: string; onChange: (value: string) => void; type?: string }) { return <label className="text-sm font-semibold text-slate-700 dark:text-slate-300">{label}<input type={type} value={value} onChange={(event) => onChange(event.target.value)} className={inputClass} /></label> }
function Detail({ label, value }: { label: string; value?: string | null }) { return <div className="rounded-lg bg-slate-50 p-3 dark:bg-slate-900"><p className="text-xs font-semibold uppercase tracking-wide text-slate-500">{label}</p><p className="mt-1 text-sm text-slate-800 dark:text-slate-200">{value || '—'}</p></div> }
function Pagination({ page, lastPage, total, onPage }: { page: number; lastPage: number; total: number; onPage: (page: number) => void }) { if (lastPage <= 1) return <p className="mt-4 text-xs text-slate-500">{total} record{total === 1 ? '' : 's'}</p>; return <div className="mt-4 flex items-center justify-between text-sm"><span className="text-slate-500">{total} records · Page {page} of {lastPage}</span><div className="flex gap-2"><button type="button" disabled={page <= 1} onClick={() => onPage(page - 1)} className="rounded-lg border border-slate-300 px-3 py-2 disabled:opacity-40 dark:border-slate-700">Previous</button><button type="button" disabled={page >= lastPage} onClick={() => onPage(page + 1)} className="rounded-lg border border-slate-300 px-3 py-2 disabled:opacity-40 dark:border-slate-700">Next</button></div></div> }
function dateTime(value?: string) { return value ? new Date(value).toLocaleString() : '—' }
function money(value?: string) { return Number(value || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 }) }
function message(error: unknown, fallback: string): string { const value = error as { response?: { data?: { message?: string; errors?: Record<string, string[]> } } }; return value?.response?.data?.message || Object.values(value?.response?.data?.errors || {})[0]?.[0] || fallback }

function EmployeeRegistrationForm({ employee, users, branches, saving, onClose, onSaving, onSaved }: { employee: Employee | null; users: UserOption[]; branches: Branch[]; saving: boolean; onClose: () => void; onSaving: (saving: boolean) => void; onSaved: (message: string) => Promise<void> }) {
  const [form, setForm] = useState({ account_mode: employee ? (employee.user ? 'link_existing' : 'record_only') : 'record_only', name: employee?.name || employee?.user?.name || '', user_id: employee?.user?.id ? String(employee.user.id) : '', login_email: '', account_role: 'sales_staff', employee_number: employee?.employee_number || '', job_title: employee?.job_title || '', department: employee?.department || '', employment_type: employee?.employment_type || 'full_time', hire_date: employee?.hire_date || '', employment_status: employee?.employment_status || 'active', phone: employee?.phone || '', address: employee?.address || '', emergency_contact_name: employee?.emergency_contact_name || '', emergency_contact_phone: employee?.emergency_contact_phone || '', branch_id: employee?.branches?.[0]?.id || '', branch_role: employee?.branches?.[0]?.role || 'sales_staff' })
  const [userSearch, setUserSearch] = useState('')
  const [photo, setPhoto] = useState<File | null>(null)
  const [error, setError] = useState('')
  const filteredUsers = useMemo(() => users.filter((user) => user.status === 'active' && `${user.name} ${user.email}`.toLowerCase().includes(userSearch.toLowerCase())), [users, userSearch])
  const submit = async () => {
    if (!form.name.trim() || !form.employee_number || (form.account_mode === 'link_existing' && !form.user_id) || (form.account_mode === 'create_login' && !form.login_email)) return
    onSaving(true); setError('')
    const data = new FormData()
    Object.entries(form).forEach(([key, value]) => { if (value) data.append(key, value) })
    if (photo) data.append('photo', photo)
    try {
      if (employee) await api.post(`/api/v1/business/employees/${employee.id}/update`, data, { headers: { 'Content-Type': 'multipart/form-data' } })
      else await api.post('/api/v1/business/employees', data, { headers: { 'Content-Type': 'multipart/form-data' } })
      await onSaved(employee ? 'Employee profile updated.' : form.account_mode === 'create_login' ? 'Employee created and login invitation sent.' : 'Employee profile created.')
    } catch (err) { setError(message(err, 'Unable to save employee profile.')) } finally { onSaving(false) }
  }
  const set = (key: string, value: string) => setForm((current) => ({ ...current, [key]: value }))
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/60 p-4"><div className="max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl dark:border-slate-800 dark:bg-slate-950 sm:p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-wide text-blue-600">{employee ? 'Edit employee' : 'New employee profile'}</p><h2 className="mt-1 text-xl font-bold text-slate-950 dark:text-white">Employee registration</h2><p className="mt-1 text-sm text-slate-500 dark:text-slate-400">A login account is optional and employee status remains separate from account status.</p></div><button type="button" onClick={onClose} aria-label="Close" className="rounded-lg p-2 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800"><X size={20} /></button></div>{error && <div className="mt-4"><ErrorState message={error} /></div>}<div className="mt-5 grid gap-4 md:grid-cols-2"><label className="text-sm font-semibold text-slate-700 dark:text-slate-300 md:col-span-2">Account option<select disabled={Boolean(employee)} value={form.account_mode} onChange={(event) => setForm({ ...form, account_mode: event.target.value, user_id: '' })} className={inputClass}><option value="record_only">Employee Record Only</option><option value="link_existing">Link Existing User Account</option><option value="create_login">Create New Login Account</option></select></label>{form.account_mode === 'link_existing' && <div className="md:col-span-2"><label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Search authorized users<input disabled={Boolean(employee)} value={userSearch} onChange={(event) => setUserSearch(event.target.value)} placeholder="Search by name or email" className={inputClass} /></label><select disabled={Boolean(employee)} value={form.user_id} onChange={(event) => setForm({ ...form, user_id: event.target.value })} className={inputClass.replace('mt-1 ', '')}><option value="">Select existing user</option>{filteredUsers.map((user) => <option key={user.id} value={user.id}>{user.name} · {user.email}</option>)}</select></div>}{form.account_mode === 'create_login' && <><Field label="Login email" value={form.login_email} onChange={(value) => set(formKey('login_email'), value)} /><label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Login role<select value={form.account_role} onChange={(event) => set('account_role', event.target.value)} className={inputClass}><option value="sales_staff">Sales staff</option><option value="salesperson">Salesperson</option><option value="cashier">Cashier</option><option value="inventory_manager">Inventory manager</option></select></label></>}<Field label="Employee name" value={form.name} onChange={(value) => set('name', value)} /><Field label="Employee ID" value={form.employee_number} onChange={(value) => set('employee_number', value)} /><Field label="Job title / position" value={form.job_title} onChange={(value) => set('job_title', value)} /><Field label="Department" value={form.department} onChange={(value) => set('department', value)} /><label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Employment type<select value={form.employment_type} onChange={(event) => set('employment_type', event.target.value)} className={inputClass}><option value="full_time">Full time</option><option value="part_time">Part time</option><option value="contract">Contract</option><option value="temporary">Temporary</option></select></label><Field label="Hire date" type="date" value={form.hire_date} onChange={(value) => set('hire_date', value)} /><label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Employment status<select value={form.employment_status} onChange={(event) => set('employment_status', event.target.value)} className={inputClass}><option value="active">Active</option><option value="on_leave">On leave</option><option value="suspended">Suspended</option><option value="terminated">Terminated</option></select></label><Field label="Phone" value={form.phone} onChange={(value) => set('phone', value)} /><Field label="Address" value={form.address} onChange={(value) => set('address', value)} /><Field label="Emergency contact" value={form.emergency_contact_name} onChange={(value) => set('emergency_contact_name', value)} /><Field label="Emergency phone" value={form.emergency_contact_phone} onChange={(value) => set('emergency_contact_phone', value)} /><label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Branch<select value={form.branch_id} onChange={(event) => set('branch_id', event.target.value)} className={inputClass}><option value="">No branch assignment</option>{branches.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></label><label className="text-sm font-semibold text-slate-700 dark:text-slate-300">Branch role<select value={form.branch_role} onChange={(event) => set('branch_role', event.target.value)} className={inputClass}><option value="sales_staff">Sales staff</option><option value="salesperson">Salesperson</option><option value="cashier">Cashier</option><option value="store_manager">Store manager</option><option value="inventory_manager">Inventory manager</option></select></label><label className="text-sm font-semibold text-slate-700 dark:text-slate-300 md:col-span-2">Profile photo<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => setPhoto(event.target.files?.[0] || null)} className={`${inputClass} file:mr-3 file:rounded-md file:border-0 file:bg-blue-50 file:px-3 file:py-1.5 file:text-sm file:font-semibold file:text-blue-700`} /></label></div><div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="rounded-[10px] border border-slate-300 px-4 py-2.5 text-sm font-semibold text-slate-700 dark:border-slate-700 dark:text-slate-200">Cancel</button><button type="button" disabled={saving || !form.name.trim() || !form.employee_number} onClick={() => { void submit() }} className="rounded-[10px] bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{saving ? 'Saving…' : 'Save employee'}</button></div></div></div>
}

function formKey(key: string): string { return key }
void EmployeeForm
